+    border: 1px solid #fecaca;
+    color: #dc2626;
+    padding: 0.75rem 1rem;
+    border-radius: 0.375rem;
+    margin-top: 1rem;
+    font-size: 0.875rem;
+}
+
+/* Work Entry / Reference Cards */
+.work-entry-card,
+.reference-card {
+    border: 1px solid #e5e7eb;
+    border-radius: 0.5rem;
+    padding: 1.25rem;
+    margin-bottom: 1rem;
+    background: #fafafa;
+}
+
+.work-entry-header,
+.reference-header {
+    display: flex;
+    justify-content: space-between;
+    align-items: center;
+    margin-bottom: 0.75rem;
+}
+
+.work-entry-header h4,
+.reference-header h4 {
+    margin: 0;
+    font-size: 1rem;
+}
+
+/* Cover Letter */
+.cover-letter-textarea {
+    resize: vertical;
+    min-height: 200px;
+    font-family: inherit;
+}
+
+.char-count {
+    text-align: right;
+    font-size: 0.8rem;
+    color: #6b7280;
+    margin-top: 0.25rem;
+}
+
+.char-count.over-limit {
+    color: #dc2626;
+    font-weight: 600;
+}
+
+/* Review Section */
+.review-section {
+    border: 1px solid #e5e7eb;
+    border-radius: 0.5rem;
+    padding: 1.25rem;
+    margin-bottom: 1rem;
+}
+
+.review-section-header {
+    display: flex;
+    justify-content: space-between;
+    align-items: center;
+    margin-bottom: 0.75rem;
+}
+
+.review-section-header h3 {
+    margin: 0;
+    font-size: 1rem;
+}
+
+.review-section dl {
+    display: grid;
+    grid-template-columns: auto 1fr;
+    gap: 0.25rem 1rem;
+    margin: 0;
+}
+
+.review-section dt {
+    font-weight: 500;
+    color: #6b7280;
+}
+
+.review-section dd {
+    margin: 0;
+}
+
+.review-work-entry {
+    padding: 0.5rem 0;
+    border-bottom: 1px solid #f3f4f6;
+}
+
+.review-work-entry:last-child {
+    border-bottom: none;
+}
+
+.review-dates {
+    font-size: 0.85rem;
+    color: #6b7280;
+}
+
+.review-reference {
+    padding: 0.5rem 0;
+    border-bottom: 1px solid #f3f4f6;
+}
+
+.review-reference:last-child {
+    border-bottom: none;
+}
+
+.review-cover-letter {
+    white-space: pre-wrap;
+    background: #f9fafb;
+    padding: 1rem;
+    border-radius: 0.375rem;
+    font-size: 0.9rem;
+}
+
+/* Submission Confirmation */
+.submission-confirmation {
+    text-align: center;
+    padding: 3rem 1rem;
+}
+
+.submission-confirmation h3 {
+    color: #16a34a;
+    font-size: 1.5rem;
+}
+
+.application-id {
+    font-size: 1.5rem;
+    font-weight: 700;
+    color: #2563eb;
+}
