            Update(Entry with { StartDate = date });
    }

    private void HandleEndDateChange(ChangeEventArgs e)
    {
        var val = e.Value?.ToString();
        if (string.IsNullOrEmpty(val))
            Update(Entry with { EndDate = null });
        else if (DateTime.TryParse(val, out var date))
            Update(Entry with { EndDate = date });
    }

